INSERT INTO `produtos` (plataforma, nome_do_jogo, categoria, classificacao_indicativa, preco, descricao, foto_capa, foto1, foto2, foto3, foto4, foto5, foto6, foto7, video) VALUES ('PC','Warframe','ação','18+',0.00,'Desperte como um guerreiro imparável e lute ao lado de seus amigos neste jogo de ação online gratuito com histórias envolventes. Enfrente facções em guerra em um amplo sistema interplanetário enquanto segue as orientações da misteriosa Lótus, aumenta o nível de seu Warframe e constrói um Arsenal com uma capacidade ofensiva destrutiva. Descubra o seu verdadeiro potencial em vastos mundos abertos neste emocionante jogo de tiro em terceira pessoa.\n\nTORNE-SE UM GUERREIRO PODEROSO\nEquipe o seu Warframe: um traje biometálico incrivelmente poderoso. Libere suas Habilidades e use uma variedade de Armas devastadoras para aniquilar hordas de inimigos sem esforço. E quando a matança acabar, você pode obter ou desbloquear instantaneamente mais de 40 Warframes diferentes, cada um com um conjunto único de poderes, para reviver o caos como preferir.\n\nBATALHE AO LADO DE AMIGOS\nForme um Esquadrão com seus amigos e ganhe Recompensas valiosas de bônus ao completar missões em grupo através de um jogo cooperativo e altamente colaborativo. Utilize as Habilidades do seu Warframe para curar aliados, redirecionar o fogo inimigo e atingir seus objetivos. Está preso em um desafio específico? A combinação de partidas no jogo facilita a conexão com Tennos aliados sempre que precisar de uma ajuda extra.\n\nEXPLORE UM SISTEMA IMENSO\nMova-se habilmente em missões terrestres com as impressionantes habilidades de parkour do seu Warframe, ou explore as estrelas e participe de enormes batalhas espaciais com sua própria nave personalizável. Perca-se nas misteriosas paisagens dos mundos abertos e descubra um sistema repleto de formas de vida fascinantes, amigáveis ​​ou hostis.\n\nDESCUBRA UMA HISTÓRIA ÉPICA\nMaravilhe-se com a história extraordinária do Sistema de Origem ao vivenciar a narrativa cinematográfica massiva do Warframe, abrangendo 5 expansões distintas e mais de 30 Jornadas baseadas em histórias. Descubra o seu poder interior e experimente a invencibilidade pela primeira vez com um dos três Warframes originais antes de começar sua trajetória, desenvolver suas habilidades e buscar a verdade sobre seu despertar.\n\nDOMINE O SEU ARSENAL\nSuas Armas iniciais são apenas o começo. Construa centenas de armamentos destrutivos, além de veículos, Companheiros e muito mais. Aprimore-os e experimente diversas combinações até encontrar a combinação certa que se adapta ao seu estilo de jogo único. Modifique o seu armamento para criar um visual ameaçador que complemente o seu equipamento personalizado.\n\nPERSONALIZAÇÕES INFINITAS\nEntrar no Sistema de Origem significa juntar-se a legiões de Tennos aliados, cada um com seus próprios Warframes, Armas e equipamentos personalizados. Com um número impressionante de Personalizações disponíveis para o seu armamento, projetar o visual perfeito para seu Warframe é um desafio infinitamente gratificante para você e seu Esquadrão.','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230410/60ce7425b864dd3c0dd855bfc66004c6f9ca4844/header.jpg?t=1775661175','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230410/ss_2e4077f215eccde84171a4b8e0f2bc8a3264c776.116x65.jpg?t=1775661175','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230410/ss_0a541a8bf59e212870ea8d82260ac1b3ae2d0354.116x65.jpg?t=1775661175','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230410/ss_ce00a212a29e9a6c1fc37b16dbd802b2844a901d.116x65.jpg?t=1775661175','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230410/ss_29355e0546599c72002b34b42fe952329df61c2e.116x65.jpg?t=1775661175','https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/230410/ss_e1d1bfebe225c85ea284ffecfe279c2695ddf3a5.116x65.jpg?t=1775661175','https://www-static.warframe.com/uploads/thumbnails/3c74688e267e97b47ab1fb8998ca467d_1600x900.png','https://tse4.mm.bing.net/th/id/OIP.X1IFXJyAEOrNVrt7BsFyBwHaEK?rs=1&pid=ImgDetMain&o=7&rm=3','<iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/5OtHw_WaDf4?si=y8Xy0NoNWr17tHAK\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PC','No Man\'s Sky(STEAM)','Acção, Aventura','10+',162.00,'Inspirado nas aventuras e na imaginação que adoramos da ficção científica clássica, No Man\'s Sky apresenta-te uma galáxia para explorares, cheia de planetas e seres sem igual, bem como de perigo e ação constantes.','https://store-images.s-microsoft.com/image/apps.56486.68818099466568894.391e0700-449d-4430-a634-7339176aa70e.d4f21bcd-310b-4bde-b82b-236031e51f98?q=90&w=480&h=270','https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/275850/251992eb497ebef3bbd6e81e2c3e80a00d2770a6/ss_251992eb497ebef3bbd6e81e2c3e80a00d2770a6.1920x1080.jpg?t=1775653502','https://gaming-cdn.com/images/products/17240/screenshot/no-man-s-sky-pc-mac-steam-wallpaper-1-big.jpg?v=1772457236','','','','','','<iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/I0pzvZ-8yIs?si=DdzZ08st52rsUvdV\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-5','ANIIMO','	Action, Adventure, RPG, Cross-Platform Multiplayer, Single-player','L',0.00,'Aniimo é um RPG de mundo aberto gratuito de última geração, com foco na captura de criaturas. No vasto continente de Idyll, você encontrará inúmeras criaturas únicas conhecidas como Aniimo. Interaja com elas e experimente a beleza deste mundo sob uma perspectiva totalmente nova e com novas habilidades.\nVocê também pode viajar para uma metrópole flutuante, onde encontrará outros Exploradores, compartilhará histórias e participará de batalhas competitivas emocionantes. Escolha seu Aniimo e embarque em uma jornada épica repleta de exploração, descobertas e aventuras!','https://gaming-cdn.com/images/products/22153/616x353/aniimo-playstation-5-playstation-store-cover.jpg?v=1774259490','https://gaming-cdn.com/images/products/22153/screenshot/aniimo-playstation-5-playstation-store-wallpaper-1.jpg?v=1774259490','https://gaming-cdn.com/images/products/22153/screenshot/aniimo-playstation-5-playstation-store-wallpaper-2.jpg?v=1774259490','https://www.instant-gaming.com/en/22153-download-aniimo-playstation-5-playstation-store/?_gl=1*awa638*_up*MQ..*_gs*MQ..&gclid=EAIaIQobChMIk93qtN3gkwMVU1NIAB0acjjREAAYASAAEgLF2vD_BwE&gbraid=0AAAAADNzuvWcl2xfxh_X-jo4vMXhBKC6R#gallery-3','https://gaming-cdn.com/images/products/22153/screenshot/aniimo-playstation-5-playstation-store-wallpaper-3.jpg?v=1774259490','https://gaming-cdn.com/images/products/22153/screenshot/aniimo-playstation-5-playstation-store-wallpaper-4.jpg?v=1774259490','https://gaming-cdn.com/images/products/22153/screenshot/aniimo-playstation-5-playstation-store-wallpaper-5.jpg?v=1774259490',NULL,'<iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/JOuWSb2S_Eg\" title=\"Aniimo Trailer | A New World of Adventure | Pre-Register Now!\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-4','TopSpin','Esportes','L',77.48,'JOGABILIDADE AUTÊNTICA\nMecânicas de jogo avançadas, física realista e visuais imersivos são o coração de TopSpin 2K25. Vários jogadores profissionais em TopSpin 2K25 possuem animações personalizadas de forehand, backhand e saque, refinadas para replicar seus movimentos na vida real. No saibro, deslizar pela quadra levanta poeira e deixa marcas no chão, enquanto na grama o desgaste se torna mais visível conforme você avança no torneio. Alcance precisão milimétrica na quadra com o novo Medidor de Tempo e execute o saque perfeito com a nova Mecânica de Saque.\n\nMULTIJOGADOR LOCAL\nReúna seus amigos e familiares para competir em partidas intensas, frente a frente, na mesma tela. O Modo Exibição Offline suporta até dois jogadores em partidas individuais e até quatro jogadores em partidas de duplas, oferecendo diversão e rivalidade sem fim.\n\nEXPERIMENTE COM ESTILOS DE JOGO\nVocê prefere uma estratégia defensiva sólida ou se concentra mais em saques dominantes? TopSpin 2K25 apresenta quatro estilos de jogo diferentes, cada um com suas próprias vantagens e habilidades únicas. Escolha entre os estilos Versátil, Linha de Base Ofensiva, Linha de Base Defensiva e Saque e Voleio. Adote o estilo de jogo do seu jogador profissional favorito ou experimente e crie MyPLAYERs híbridos com base nesses estilos principais.\n\nGANHE O GRAND SLAM DA CARREIRA\nViaje pelo mundo como um profissional promissor, enfrente os maiores nomes do tênis e domine a Quadra Central em Wimbledon, Roland-Garros, no US Open e no Australian Open enquanto busca se tornar um campeão de Grand Slam online no MyCAREER.\n\nDOMINE O TRIBUNAL ONLINE\nTeste as habilidades do seu MyPLAYER e mostre seu talento no tênis no Circuito Mundial ou entre no Circuito 2K como um profissional jogável, desafiando jogadores do mundo todo com suporte para cross-play. Ou então, divirta-se com seus amigos do 2K e de outras plataformas em partidas individuais privadas online no Modo Exibição Online!\n\nPERSONALIZE SEU MyPLAYER\nCrie um MyPLAYER personalizado para o seu estilo de jogo e defina seu visual na quadra! Com uma ampla gama de opções de personalização, você pode ajustar seus atributos e ganhar novos treinadores, equipamentos e acessórios da adidas, HEAD, Lacoste, New Balance, Nike, Wilson e muito mais.','https://gaming-cdn.com/images/products/16507/616x353/topspin-2k25-playstation-4-playstation-store-cover.jpg?v=1759410376','https://gaming-cdn.com/img/products/15714/pcover/1000x350/15714.jpg?v=1715241013','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-1.jpg?v=1759410376','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-2.jpg?v=1759410376','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-4.jpg?v=1759410376','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-3.jpg?v=1759410376','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-5.jpg?v=1759410376',NULL,'<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/hlIGNumuNT4\" title=\"TopSpin 2K25 | Official Announce Trailer | 2K\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-4-5','Resident Evil 4 ','Ação , Aventura','18 +',59.09,'Este conjunto pode estar incluído em algumas edições do jogo. Tenha cuidado para não comprar conteúdo ao qual você já tenha acesso.\n- Os itens contidos neste conjunto podem ser comprados individualmente e também são vendidos em conjunto com outros conjuntos.\n- Este conteúdo requer a versão completa do jogo, vendida separadamente. Você também pode precisar atualizar seu jogo para a versão mais recente.\n\nEste conjunto contém os seguintes itens:\n- Trajes de Leon e Ashley: \'Casual\'\n- Trajes de Leon e Ashley: \'Romântico\'\n- Traje e Filtro de Leon: \'Herói\'\n- Traje e Filtro de Leon: \'Vilão\'\n- Acessório de Leon: \'Óculos de Sol (Esportivo)\'\n- Arma Deluxe: \'Sentinel Nine\'\n- Arma Deluxe: \'Skull Shaker\'\n- \'Versão Original\' Troca de Trilha Sonora\n- Mapa do Tesouro: Expansão\n\nO conteúdo a seguir é para a história principal de Resident Evil 4. Ele não é compatível ou é apenas parcialmente compatível com o conteúdo extra pago, Separate Ways:\n- Traje e Filtro do Leon: \'Herói\'\n- Traje e Filtro do Leon: \'Vilão\'\n- Arma Deluxe: \'Sentinel Nine\'\n- Arma Deluxe: \'Skull Shaker\'\n- \'Versão Original\' Troca de Trilha Sonora\n- Mapa do Tesouro: Expansão','https://gaming-cdn.com/images/products/22045/616x353/resident-evil-4-extra-dlc-pack-playstation-4-playstation-5-playstation-store-cover.jpg?v=1775547448','https://gaming-cdn.com/img/products/16189/pcover/1000x350/16189.jpg?v=1774968046','FOTO2','FOTO3','FOTO4','FOTO5','FOTO6',NULL,'<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/FBZqcVXeTFc\" title=\"Resident Evil 4 2005 | Official Trailer | #game\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-5','Do Nunca ao Sempre ','	Ação','14+',0.00,'NTE é um RPG sobrenatural de mundo aberto desenvolvido pela Hotta Studio. A história começa na cidade de Hethereau, onde você joga como o primeiro Caçador de Anomalias \"sem licença\". Você se juntará à loja de antiguidades Eibon, que depende de encomendas de Anomalias do público para se manter. Ao lado de seus diversos e extraordinários parceiros, você explorará vários mistérios urbanos, vivenciando uma série de aventuras repletas de risos e lágrimas, e criando sua saga urbana única.','https://gaming-cdn.com/images/products/20168/616x353/neverness-to-everness-playstation-5-playstation-store-cover.jpg?v=1772105288','https://gaming-cdn.com/img/products/20168/pcover/1000x350/20168.jpg?v=1772105288','https://gaming-cdn.com/images/products/20168/screenshot/neverness-to-everness-playstation-5-playstation-store-wallpaper-1.jpg?v=1772105288','https://gaming-cdn.com/images/products/20168/screenshot/neverness-to-everness-playstation-5-playstation-store-wallpaper-2.jpg?v=1772105288','https://gaming-cdn.com/images/products/20168/screenshot/neverness-to-everness-playstation-5-playstation-store-wallpaper-2.jpg?v=1772105288','https://gaming-cdn.com/images/products/20168/screenshot/neverness-to-everness-playstation-5-playstation-store-wallpaper-4.jpg?v=1772105288','https://gaming-cdn.com/images/products/20168/screenshot/neverness-to-everness-playstation-5-playstation-store-wallpaper-5.jpg?v=1772105288',NULL,'<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/bO1n68MRshY\" title=\"Neverness to Everness - Gameplay Trailer | gamescom 2025\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-4','TopSpin','Esportes','L',77.48,'JOGABILIDADE AUTÊNTICA\nMecânicas de jogo avançadas, física realista e visuais imersivos são o coração de TopSpin 2K25. Vários jogadores profissionais em TopSpin 2K25 possuem animações personalizadas de forehand, backhand e saque, refinadas para replicar seus movimentos na vida real. No saibro, deslizar pela quadra levanta poeira e deixa marcas no chão, enquanto na grama o desgaste se torna mais visível conforme você avança no torneio. Alcance precisão milimétrica na quadra com o novo Medidor de Tempo e execute o saque perfeito com a nova Mecânica de Saque.\n\nMULTIJOGADOR LOCAL\nReúna seus amigos e familiares para competir em partidas intensas, frente a frente, na mesma tela. O Modo Exibição Offline suporta até dois jogadores em partidas individuais e até quatro jogadores em partidas de duplas, oferecendo diversão e rivalidade sem fim.\n\nEXPERIMENTE COM ESTILOS DE JOGO\nVocê prefere uma estratégia defensiva sólida ou se concentra mais em saques dominantes? TopSpin 2K25 apresenta quatro estilos de jogo diferentes, cada um com suas próprias vantagens e habilidades únicas. Escolha entre os estilos Versátil, Linha de Base Ofensiva, Linha de Base Defensiva e Saque e Voleio. Adote o estilo de jogo do seu jogador profissional favorito ou experimente e crie MyPLAYERs híbridos com base nesses estilos principais.\n\nGANHE O GRAND SLAM DA CARREIRA\nViaje pelo mundo como um profissional promissor, enfrente os maiores nomes do tênis e domine a Quadra Central em Wimbledon, Roland-Garros, no US Open e no Australian Open enquanto busca se tornar um campeão de Grand Slam online no MyCAREER.\n\nDOMINE O TRIBUNAL ONLINE\nTeste as habilidades do seu MyPLAYER e mostre seu talento no tênis no Circuito Mundial ou entre no Circuito 2K como um profissional jogável, desafiando jogadores do mundo todo com suporte para cross-play. Ou então, divirta-se com seus amigos do 2K e de outras plataformas em partidas individuais privadas online no Modo Exibição Online!\n\nPERSONALIZE SEU MyPLAYER\nCrie um MyPLAYER personalizado para o seu estilo de jogo e defina seu visual na quadra! Com uma ampla gama de opções de personalização, você pode ajustar seus atributos e ganhar novos treinadores, equipamentos e acessórios da adidas, HEAD, Lacoste, New Balance, Nike, Wilson e muito mais.','https://gaming-cdn.com/images/products/16507/616x353/topspin-2k25-playstation-4-playstation-store-cover.jpg?v=1759410376','https://gaming-cdn.com/img/products/15714/pcover/1000x350/15714.jpg?v=1715241013','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-1.jpg?v=1759410376','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-2.jpg?v=1759410376','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-4.jpg?v=1759410376','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-3.jpg?v=1759410376','https://gaming-cdn.com/images/products/16507/screenshot/topspin-2k25-playstation-4-playstation-store-wallpaper-5.jpg?v=1759410376',NULL,''),('PLAYSTATION-5','Starfield','	RPG','18+',249.90,'O jogo se passa 300 anos no futuro, quando a exploração espacial não só acontece regularmente, como se tornou algo comum. Você é membro da Constellation, uma organização de exploradores espaciais – a última organização de exploradores espaciais, na verdade. Não perca tempo se perguntando o que aconteceu com os outros exploradores e por que eles foram reduzidos a um único grupo, vamos direto ao jogo!\n\nAs naves da Constellation têm uma vibe que mistura steampunk com a NASA de forma perfeita. Os desenvolvedores apelidaram de \"NASA-punk\", e ela combina a elegância futurista com a simplicidade e o conforto de uma nave convidativa e aconchegante, sem comprometer a segurança de que as naves realmente voarão e manterão você vivo enquanto você viaja!','https://gaming-cdn.com/images/products/22136/616x353/starfield-playstation-5-playstation-store-cover.jpg?v=1773761950','https://gaming-cdn.com/img/products/2675/pcover/1000x350/2675.jpg?v=1708361145','https://gaming-cdn.com/images/products/22136/screenshot/starfield-playstation-5-playstation-store-wallpaper-1.jpg?v=1773761950','https://gaming-cdn.com/images/products/22136/screenshot/starfield-playstation-5-playstation-store-wallpaper-2.jpg?v=1773761950','https://gaming-cdn.com/images/products/22136/screenshot/starfield-playstation-5-playstation-store-wallpaper-3.jpg?v=1773761950','https://gaming-cdn.com/images/products/22136/screenshot/starfield-playstation-5-playstation-store-wallpaper-4.jpg?v=1773761950','https://gaming-cdn.com/images/products/22136/screenshot/starfield-playstation-5-playstation-store-wallpaper-5.jpg?v=1773761950',NULL,'<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/pYqyVpCV-3c\" title=\"Starfield: Official Teaser Trailer\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-5','Warhammer 40.000: Space Marine 2','	Ação , Aventura , RPG','18+',138.48,'Economize em conteúdo adicional para Warhammer 40.000: Space Marine 2 com o Passe de Temporada e receba armaduras, armas e itens cosméticos de Campeões dos seus capítulos favoritos de Space Marines ao longo de quatro fases. O conteúdo pode ser baixado da loja ou dentro do jogo após o lançamento.\n\nJá disponível:\n\n- Pacote Cosmético Ultramarines\n\n- Pacote de Capítulos dos Anjos Sombrios\n\n- Pacote Campeão Salamandras\n\nPacote Cosmético da Guarda Corvo\n\n- Pacote Campeão dos Punhos Imperiais\n\n- Pacote de Capítulo dos Lobos Espaciais\n\n- Pacote de cosméticos dos Anjos Sangrentos\n\n- Pacote de Capítulos Cicatrizes Brancas\n\nO Passe de Temporada está incluído na Edição de 2º Aniversário e na Edição de 1º Aniversário. Requer o jogo base Warhammer 40.000: Space Marine 2.\n\nAo adquirir este pacote, você desbloqueia parte do seu conteúdo no menu de personalização. Você pode desbloquear o conteúdo associado com pontos de requisição obtidos nos modos PvP e PvE.\n\nPara obter mais detalhes, consulte as descrições de cada DLC.','https://gaming-cdn.com/images/products/21897/616x353/warhammer-40-000-space-marine-2-season-pass-playstation-5-playstation-store-cover.jpg?v=1773649022','https://gaming-cdn.com/img/products/20096/pcover/1000x350/20096.jpg?v=1755511651','https://gaming-cdn.com/images/products/21897/screenshot/warhammer-40-000-space-marine-2-season-pass-playstation-5-playstation-store-wallpaper-1.jpg?v=1773649022','https://gaming-cdn.com/images/products/21897/screenshot/warhammer-40-000-space-marine-2-season-pass-playstation-5-playstation-store-wallpaper-2.jpg?v=1773649022','https://gaming-cdn.com/images/products/21897/screenshot/warhammer-40-000-space-marine-2-season-pass-playstation-5-playstation-store-wallpaper-3.jpg?v=1773649022','FOTO5','FOTO6',NULL,'<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/A_HljUo8Jjk\" title=\"Warhammer 40k: Space Marine II Cinematic Trailer | Game Awards 2021\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-5','Marés do Amanhã','	Aventura ','L',0.00,'O jogo se passa em um mundo pós-apocalíptico onde a terra foi inundada. Você assume o papel de um \"Tidewalker\" (Caminhante das Marés), navegando por oceanos e tomando decisões cruciais para moldar o destino desse novo mundo.','https://gaming-cdn.com/images/products/19476/616x353/tides-of-tomorrow-playstation-5-playstation-store-cover.jpg?v=1768388482','https://gaming-cdn.com/img/products/19323/pcover/1000x350/19323.jpg?v=1768832850','https://gaming-cdn.com/images/products/19476/screenshot/tides-of-tomorrow-playstation-5-playstation-store-wallpaper-1.jpg?v=1768388482','https://gaming-cdn.com/images/products/19476/screenshot/tides-of-tomorrow-playstation-5-playstation-store-wallpaper-2.jpg?v=1768388482','https://gaming-cdn.com/images/products/19476/screenshot/tides-of-tomorrow-playstation-5-playstation-store-wallpaper-3.jpg?v=1768388482','https://gaming-cdn.com/images/products/19476/screenshot/tides-of-tomorrow-playstation-5-playstation-store-wallpaper-4.jpg?v=1768388482','https://gaming-cdn.com/images/products/19476/screenshot/tides-of-tomorrow-playstation-5-playstation-store-wallpaper-5.jpg?v=1768388482',NULL,'<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/miLQSW3n1jA\" title=\"Tides of Tomorrow - Release Trailer | PS5 Games\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-5','Saros','	Ação','14+',0.00,'Sob a sombra de um eclipse ameaçador, Arjun Devraj (Rahul Kohli) é um executor Soltari que não medirá esforços para descobrir os mistérios de Carcosa, um mundo de segredos sombrios e habitantes hostis.\n\nDomine o eletrizante combate de balé de balas – uma jogabilidade intensa focada em projéteis com uma estética única e neon – para derrotar inimigos ferozes e enfrentar chefes espetaculares.','https://gaming-cdn.com/images/products/18713/616x353/saros-playstation-5-playstation-store-cover.jpg?v=1768833581','https://gaming-cdn.com/img/products/18713/pcover/1000x350/18713.jpg?v=1768833581','https://gaming-cdn.com/images/products/18713/screenshot/saros-playstation-5-playstation-store-wallpaper-1.jpg?v=1768833581','https://gaming-cdn.com/images/products/18713/screenshot/saros-playstation-5-playstation-store-wallpaper-2.jpg?v=1768833581','https://gaming-cdn.com/images/products/18713/screenshot/saros-playstation-5-playstation-store-wallpaper-3.jpg?v=1768833581','https://gaming-cdn.com/images/products/18713/screenshot/saros-playstation-5-playstation-store-wallpaper-4.jpg?v=1768833581','https://gaming-cdn.com/images/products/18713/screenshot/saros-playstation-5-playstation-store-wallpaper-5.jpg?v=1768833581',NULL,'<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/rj_1CzKUR4w\" title=\"Saros - Launch Trailer | PS5 Games\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-5','Star Wars Jedi: Survivor Deluxe Upgrade','	Ação , Aventura','14+',82.75,'O pacote de expansão STAR WARS Jedi: Survivor™ Deluxe* contém itens cosméticos exclusivos inspirados em alguns dos maiores heróis da galáxia. O Pacote Cosmético “Herói Galáctico” inclui: Item Cosmético “Vagabundo” — Vista-se com este item cosmético inspirado no malandro mais reconhecido da galáxia: Han Solo™. Item Cosmético “Resistente” para BD-1 — Equipe BD-1 com este equipamento robusto e resistente que o deixará pronto para qualquer aventura.','https://gaming-cdn.com/images/products/16854/616x353/star-wars-jedi-survivor-deluxe-upgrade-playstation-5-playstation-store-cover.jpg?v=1759167537','https://gaming-cdn.com/img/products/16145/pcover/1920x620/16145.jpg?v=1730296838','https://gaming-cdn.com/images/products/16854/screenshot/star-wars-jedi-survivor-deluxe-upgrade-playstation-5-playstation-store-wallpaper-1.jpg?v=1759167537','https://gaming-cdn.com/images/products/16854/screenshot/star-wars-jedi-survivor-deluxe-upgrade-playstation-5-playstation-store-wallpaper-2.jpg?v=1759167537','https://gaming-cdn.com/images/products/16854/screenshot/star-wars-jedi-survivor-deluxe-upgrade-playstation-5-playstation-store-wallpaper-3.jpg?v=1759167537','https://gaming-cdn.com/images/products/16854/screenshot/star-wars-jedi-survivor-deluxe-upgrade-playstation-5-playstation-store-wallpaper-4.jpg?v=1759167537','https://gaming-cdn.com/images/products/16854/screenshot/star-wars-jedi-survivor-deluxe-upgrade-playstation-5-playstation-store-wallpaper-5.jpg?v=1759167537',NULL,'<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/VRaobDJjiec\" title=\"Star Wars Jedi: Survivor - Trailer de divulgação oficial\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('PLAYSTATION-5','Professor Layton and The New World of Steam','	Aventura ','10+',0.00,'De uma série com mais de 18 milhões de unidades vendidas em todo o mundo.\n\nResolva enigmas épicos enquanto avança na história desta aventura de fantasia e quebra-cabeças.\n\nO mais novo título da série Layton.\n\nO Professor Layton e Luke enfrentam novos enigmas em um cenário inédito.','https://gaming-cdn.com/images/products/22312/616x353/professor-layton-and-the-new-world-of-steam-playstation-5-playstation-store-cover.jpg?v=1775825528','https://gaming-cdn.com/images/products/22312/616x353/professor-layton-and-the-new-world-of-steam-playstation-5-playstation-store-cover.jpg?v=1775825528','https://gaming-cdn.com/images/products/22312/616x353/professor-layton-and-the-new-world-of-steam-playstation-5-playstation-store-cover.jpg?v=1775825528','https://gaming-cdn.com/images/products/22312/screenshot/professor-layton-and-the-new-world-of-steam-playstation-5-playstation-store-wallpaper-2.jpg?v=1775825528','https://gaming-cdn.com/images/products/22312/screenshot/professor-layton-and-the-new-world-of-steam-playstation-5-playstation-store-wallpaper-3.jpg?v=1775825528','https://gaming-cdn.com/images/products/22312/screenshot/professor-layton-and-the-new-world-of-steam-playstation-5-playstation-store-wallpaper-4.jpg?v=1775825528','https://gaming-cdn.com/images/products/22312/screenshot/professor-layton-and-the-new-world-of-steam-playstation-5-playstation-store-wallpaper-5.jpg?v=1775825528','FOTO7','<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/wuy2XXuAvyY\" title=\"Professor Layton and the New World of Steam - Official Trailer\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('Xbox One & Xbox Series X|S','Call of Duty: Modern Warfare III - Edição Vault','Cooperation, Online Co-op, Multiplayer, Cross-Platform Multiplayer, Single-player, Acção','18+',494.35,'A Vault Edition inclui o jogo completo (versões Xbox One e Xbox Series X|S), o Pack de Operacional Nemesis, 2 depósitos de armas, BlackCell por 1 temporada e 30 saltos de escalão adicionais.\nEm Modern Warfare III, o Capitão Price e a Task Force 141 enfrentam a maior ameaça até agora: Vladimir Makarov, numa campanha intensa que dá continuidade direta aos eventos de MWII.\n\n\nO jogo celebra os 20 anos de Call of Duty com um multijogador robusto, trazendo 16 mapas clássicos de MW2 (2009) modernizados no lançamento e novos mapas 6v6 adicionados ao longo das temporadas.\nHá também um novo modo Zombies em mundo aberto, onde equipas cooperam para sobreviver a hordas de mortos-vivos no maior mapa Zombies já criado, com história inédita, missões e segredos.','https://gaming-cdn.com/images/products/15073/616x353/call-of-duty-modern-warfare-iii-edicao-vault-vault-edition-xbox-series-x-s-xbox-one-jogo-microsoft-store-cover.jpg?v=1739354824','https://gaming-cdn.com/images/products/15073/screenshot/call-of-duty-modern-warfare-iii-edicao-vault-vault-edition-xbox-series-x-s-xbox-one-jogo-microsoft-store-wallpaper-1.jpg?v=1739354824','https://www.instant-gaming.com/pt/15073-comprar-call-of-duty-modern-warfare-iii-edicao-vault-vault-edition-xbox-series-x-s-xbox-one-jogo-microsoft-store/','https://gaming-cdn.com/images/products/15073/screenshot/call-of-duty-modern-warfare-iii-edicao-vault-vault-edition-xbox-series-x-s-xbox-one-jogo-microsoft-store-wallpaper-4.jpg?v=1739354824','https://www.instant-gaming.com/pt/15073-comprar-call-of-duty-modern-warfare-iii-edicao-vault-vault-edition-xbox-series-x-s-xbox-one-jogo-microsoft-store/','https://www.instant-gaming.com/pt/15073-comprar-call-of-duty-modern-warfare-iii-edicao-vault-vault-edition-xbox-series-x-s-xbox-one-jogo-microsoft-store/','https://gaming-cdn.com/img/products/13587/pcover/1000x350/13587.jpg?v=1720108480','https://gaming-cdn.com/images/products/15073/616x353/call-of-duty-modern-warfare-iii-edicao-vault-vault-edition-xbox-series-x-s-xbox-one-jogo-microsoft-store-cover.jpg?v=1739354824','<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/i3IsLrPeZG8\" title=\"Call of Duty: Modern Warfare III - Gameplay Reveal Trailer | PS5 &amp; PS4 Games\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('Xbox Series X|S','EA Sports FC 25','Esporte / Simulador de Futebol','L',119.73,'O EA SPORTS FC 25 dá-te mais formas de ganhar pelo teu clube. Junta-te a amigos nos teus modos favoritos com o novo Rush 5x5 e conduz o teu clube até à vitória: o FC IQ dá-te mais controlo tático do que nunca','https://gaming-cdn.com/images/products/17255/616x353/ea-sports-fc-25-xbox-series-x-s-jogo-microsoft-store-cover.jpg?v=1739272281','https://gaming-cdn.com/images/products/17255/screenshot/ea-sports-fc-25-xbox-series-x-s-jogo-microsoft-store-wallpaper-1.jpg?v=1739272281','https://gaming-cdn.com/images/products/17255/screenshot/ea-sports-fc-25-xbox-series-x-s-jogo-microsoft-store-wallpaper-2.jpg?v=1739272281','https://gaming-cdn.com/images/products/17255/screenshot/ea-sports-fc-25-xbox-series-x-s-jogo-microsoft-store-wallpaper-4.jpg?v=1739272281','https://gaming-cdn.com/images/products/17255/screenshot/ea-sports-fc-25-xbox-series-x-s-jogo-microsoft-store-wallpaper-3.jpg?v=1739272281','https://gaming-cdn.com/images/products/17255/screenshot/ea-sports-fc-25-xbox-series-x-s-jogo-microsoft-store-wallpaper-5.jpg?v=1739272281','https://gaming-cdn.com/img/products/17255/pcover/1000x350/17255.jpg?v=1739272281','https://gaming-cdn.com/images/products/17255/616x353/ea-sports-fc-25-xbox-series-x-s-jogo-microsoft-store-cover.jpg?v=1739272281','<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/pBM2xyco_Kg\" title=\"EA SPORTS FC 25 | Trailer oficial de revelação\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('Xbox Series X|S','Dragons Dogma 2','Single-player, Acção, Adventure, RPG','18+',309.87,'Parte numa grande aventura, Arisen!\n\nDragon’s Dogma faz parte de uma série de RPGs de ação para um jogador guiados pela narrativa que te permite escolher a tua própria experiência. Desde a aparência do Arisen, a sua vocação, o seu grupo, como abordar diferentes situações e muito mais. Agora, nesta aguardada sequela, prepara-te para conhecer o intenso mundo de fantasia de Dragon’s Dogma 2. Nunca te vais cansar de o explorar.\n\nNa tua jornada, serás acompanhado por misteriosos seres sobrenaturais chamados Peões, numa aventura tão única que parecerá que estarás junto de outros jogadores.\n\nEstes elementos ganham mais relevo através de uma tecnologia com base na física, inteligência artificial (IA) e gráficos de última geração. Tudo isto contribui para que Dragons Dogma 2 te ofereça um mundo de fantasia verdadeiramente imersivo.','https://gaming-cdn.com/images/products/15666/616x353/dragon-s-dogma-2-xbox-series-x-s-jogo-microsoft-store-cover.jpg?v=1738774505','https://gaming-cdn.com/images/products/15666/screenshot/dragon-s-dogma-2-xbox-series-x-s-jogo-microsoft-store-wallpaper-1.jpg?v=1738774505','https://gaming-cdn.com/images/products/15666/screenshot/dragon-s-dogma-2-xbox-series-x-s-jogo-microsoft-store-wallpaper-2.jpg?v=1738774505','https://gaming-cdn.com/images/products/15666/screenshot/dragon-s-dogma-2-xbox-series-x-s-jogo-microsoft-store-wallpaper-4.jpg?v=1738774505','https://gaming-cdn.com/images/products/15666/screenshot/dragon-s-dogma-2-xbox-series-x-s-jogo-microsoft-store-wallpaper-3.jpg?v=1738774505','https://gaming-cdn.com/images/products/15666/screenshot/dragon-s-dogma-2-xbox-series-x-s-jogo-microsoft-store-wallpaper-5.jpg?v=1738774505','https://gaming-cdn.com/img/products/15666/pcover/1000x350/15666.jpg?v=1738774505','https://gaming-cdn.com/images/products/15666/616x353/dragon-s-dogma-2-xbox-series-x-s-jogo-microsoft-store-cover.jpg?v=1738774505','<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/Td4Kek2gtYM\" title=\"Dragon&#39;s Dogma 2 - Official Trailer (ft. Ian McShane)\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('Xbox One & Xbox Series X|S','NBA 2K25','Esportes','L',62.49,'rilha o teu percurso na competição, construindo o teu legado na MyCAREER e MyTEAM, e explora a MyNBA e The W na Xbox Series X|S ou MyLEAGUE na Xbox One. Expressa a tua personalidade com uma ampla gama de opções de personalização e explora a novíssima City (para a Xbox Series X|S) ou a metrópole urbana no Neighborhood (para a Xbox One).\n\nCOM TECNOLOGIA ProPLAY\n\nExperimenta as manobras que só os teus jogadores favoritos da NBA conseguem concretizar, enquanto afinas a tua técnica para fazeres jogadas que vão alterar o rumo do campeonato. Vive mais o teu jogo com ProPLAY na Xbox Series X|S, a tecnologia imersiva que traduz as imagens reais da NBA para o ambiente de jogo mais envolvente de sempre. Chega mais perto e joga lado a lado com as tuas estrelas favoritas da NBA, mergulhando na experiência da NBA mais autêntica de sempre.\n\nCOMPETE NA MyCAREER\n\nHonra as lendas da NBA em MyCAREER ao eclipsares todos os seus recordes do passado, inaugurando a melhor dinastia que o desporto alguma vez conheceu. A City na Xbox Series X|S é o derradeiro campo de jogos onde podes comprovar o teu valor. Joga a sério no parque e diverte-te a mostrar os teus melhores truques ou compete nos novos pavilhões a estrear na cidade. Ou domina o novo Neighborhood na Xbox One enquanto completas missões, ganhas recompensas e superas os teus Rivais em modos de jogo novos e antigos.\n\nA TUA MyTEAM, A TUA VISÂO\n\nA competição sobe de nível na MyTEAM. Desafia os plantéis das equipas rivais com a tua convocatória MyTEAM e enfrenta, semana após semana, outros jogadores de elite no King of the Court. Prova que mereces ser coroado como o melhor entre os melhores neste evento exclusivo.\n\nPlay Now, MyNBA, The W e MyLEAGUE estão disponíveis offline. Todos os outros modos e funções requerem ligação à Internet e podem exigir o registo numa conta online (varia para maiores de 13 anos).','https://gaming-cdn.com/images/products/17198/616x353/nba-2k25-xbox-series-x-s-xbox-one-jogo-microsoft-store-cover.jpg?v=1739271128','https://gaming-cdn.com/img/products/17198/pcover/1000x350/17198.jpg?v=1739271128','https://gaming-cdn.com/images/products/17198/screenshot/nba-2k25-xbox-series-x-s-xbox-one-jogo-microsoft-store-wallpaper-1.jpg?v=1739271128','https://gaming-cdn.com/images/products/17198/screenshot/nba-2k25-xbox-series-x-s-xbox-one-jogo-microsoft-store-wallpaper-2.jpg?v=1739271128','https://gaming-cdn.com/images/products/17198/screenshot/nba-2k25-xbox-series-x-s-xbox-one-jogo-microsoft-store-wallpaper-4.jpg?v=1739271128','https://gaming-cdn.com/images/products/17198/screenshot/nba-2k25-xbox-series-x-s-xbox-one-jogo-microsoft-store-wallpaper-3.jpg?v=1739271128','https://gaming-cdn.com/images/products/17198/screenshot/nba-2k25-xbox-series-x-s-xbox-one-jogo-microsoft-store-wallpaper-5-thumbv2.jpg?v=1739271128','https://gaming-cdn.com/images/products/17198/616x353/nba-2k25-xbox-series-x-s-xbox-one-jogo-microsoft-store-cover.jpg?v=1739271128','<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/zwQ9RjfvJN0\" title=\"NBA 2K25 | Official Gameplay Trailer\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('Xbox Series X|S','Resident Evil Requiem ','Ação, Aventura, Single-player','18+',309.39,'Prepara-te para fugir à morte nesta experiência de gelar o sangue.\n\nEstá a chegar uma nova era do terror de sobrevivência. Esta narrativa irá combinar avanços tecnológicos com a vasta experiência da equipa de desenvolvimento, de modo a criar uma história com personagens cativantes e uma jogabilidade mais imersiva do que nunca.','https://gaming-cdn.com/images/products/21511/616x353/resident-evil-requiem-xbox-series-x-s-microsoft-store-cover.jpg?v=1772017460','https://gaming-cdn.com/img/products/9000/pcover/1000x350/9000.jpg?v=1771856835','https://gaming-cdn.com/images/products/21511/screenshot/resident-evil-requiem-xbox-series-x-s-microsoft-store-wallpaper-1.jpg?v=1772017460','https://gaming-cdn.com/images/products/21511/screenshot/resident-evil-requiem-xbox-series-x-s-microsoft-store-wallpaper-2.jpg?v=1772017460','https://gaming-cdn.com/images/products/21511/screenshot/resident-evil-requiem-xbox-series-x-s-microsoft-store-wallpaper-4-thumbv2.jpg?v=1772017460','https://gaming-cdn.com/images/products/21511/screenshot/resident-evil-requiem-xbox-series-x-s-microsoft-store-wallpaper-3.jpg?v=1772017460','https://gaming-cdn.com/images/products/21511/screenshot/resident-evil-requiem-xbox-series-x-s-microsoft-store-wallpaper-5-thumbv2.jpg?v=1772017460','https://gaming-cdn.com/images/products/21511/616x353/resident-evil-requiem-xbox-series-x-s-microsoft-store-cover.jpg?v=1772017460','<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/hYcpNzFNZrk\" title=\"Resident Evil Requiem - 3º Trailer\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('Xbox Series X|S','Hogwarts Legacy','\nUm jogador, Ação, Aventura, RPG','12+',59.45,'Hogwarts Legacy é um RPG de ação de mundo aberto que decorre na realidade da série Harry Potter. Embarca numa aventura por locais novos e outros já familiares, explora e descobre criaturas mágicas, personaliza a tua personagem, cria poções, domina feitiços, melhora talentos e torna-te o feiticeiro que ambicionas ser.\n\nVive Hogwarts no século XIX. A tua personagem é um aluno que guarda a chave de um antigo segredo que ameaça destruir o mundo dos feiticeiros. Faz aliados, enfrenta feiticeiros das trevas e decide o destino do mundo da feitiçaria. O teu legado é o que fazes dele. Vive o que ainda não foi escrito.\n\nInclui a Missão Loja Assombrada em Hogsmeade que concede acesso a uma masmorra adicional, um Conjunto de Cosméticos de Lojista e uma loja no jogo em Hogsmeade.\n\nAs novas funcionalidades incluem:\n- Modo Foto\n- Reposição de talento\n\nNovos itens cosméticos já disponíveis para todos os jogadores: Os Óculos que Viveram, Uniforme e Casaco de Prisioneiro de Azkaban, Montada Hipogrifo Ónix, Receita da Poção Felix Felicis e Vassouras do Feiticeiro das Trevas (2)\n\nSe já tiveres a versão digital da Xbox One deste jogo, podes obter a versão digital da Xbox Series X|S com um desconto.','https://gaming-cdn.com/images/products/13362/616x353/hogwarts-legacy-xbox-series-x-s-jogo-microsoft-store-cover.jpg?v=1739360516','https://gaming-cdn.com/img/products/7072/pcover/1000x350/7072.jpg?v=1732564014','https://gaming-cdn.com/images/products/13362/screenshot/hogwarts-legacy-xbox-series-x-s-jogo-microsoft-store-wallpaper-1.jpg?v=1739360516','https://gaming-cdn.com/images/products/13362/screenshot/hogwarts-legacy-xbox-series-x-s-jogo-microsoft-store-wallpaper-2.jpg?v=1739360516','https://gaming-cdn.com/images/products/13362/screenshot/hogwarts-legacy-xbox-series-x-s-jogo-microsoft-store-wallpaper-4.jpg?v=1739360516','https://gaming-cdn.com/images/products/13362/screenshot/hogwarts-legacy-xbox-series-x-s-jogo-microsoft-store-wallpaper-3.jpg?v=1739360516','https://gaming-cdn.com/images/products/13362/screenshot/hogwarts-legacy-xbox-series-x-s-jogo-microsoft-store-wallpaper-5-thumbv2.jpg?v=1739360516','https://gaming-cdn.com/images/products/13362/616x353/hogwarts-legacy-xbox-series-x-s-jogo-microsoft-store-cover.jpg?v=1739360516','<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/BtyBjOW8sGY\" title=\"Hogwarts Legacy - Official Launch Trailer 4K\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('Xbox Series X|S','Avowed ','RPG','12+',297.49,'Boas-vindas à Terra Viva, uma ilha misteriosa cheia de aventura e perigo.\nSituado no mundo fictício de Eora, que foi apresentado pela primeira vez aos jogadores da franquia Pillars of Eternity, Avowed é um RPG de ação e fantasia em primeira pessoa da premiada equipe da Obsidian Entertainment.\nVocê vem de Aedyr, uma terra distante, para investigar rumores de uma praga que se espalha pela Terras Viva - uma ilha cheia de mistérios e segredos, perigos e aventuras, escolhas e consequências, e natureza selvagem. Você descobre uma conexão pessoal com a Terra Viva e um segredo antigo que ameaça destruir tudo. Será que você consegue salvar sua alma e estas terras desconhecidas das forças que ameaçam dizimá-las?\n\nAs estranhas e maravilhosas Terras Vivas\nAs Terras Vivas podem parecer um lugar desconhecido à primeira vista, mas para você, a sensação é de familiaridade, como se a ilha estivesse pedindo ajuda. Explore uma ilha que abriga muitos ambientes e paisagens diferentes, cada um com seu ecossistema único.\n\nCombate visceral para jogar como quiser\nMisture e combine espadas, feitiços, armas e escudos para lutar como quiser. Explore seu grimório em busca de feitiços para prender, congelar ou queimar inimigos, golpeá-los com o escudo ou usar arcos para atacar à distância.\n\nCompanhias na jornada\nCompanheiros de diversas espécies lutarão ao seu lado, com conjuntos únicos de habilidades. De um ex-mercenário a um mago excêntrico, os companheiros farão parte de sua jornada e serão moldados pelas escolhas que você faz enquanto ajuda nas missões deles.\n\n© Microsoft 2025. Todos os direitos reservados. Microsoft, Obsidian Entertainment, o logotipo da Obsidian Entertainment e Avowed são marcas registradas do grupo empresarial Microsoft. Todas as outras marcas registradas são de propriedade de seus respectivos donos. É necessário aceitar o Contrato de Serviços da Microsoft e a Política de Privacidade para jogar. É necessário registrar sua conta Microsoft para jogar em diferentes plataformas. Requer conexão com a Internet. Os recursos, os serviços online e os requisitos de sistema podem variar conforme o país e estão sujeitos a alterações ou descontinuidade ao longo do tempo.','https://gaming-cdn.com/images/products/18020/616x353/avowed-pc-xbox-series-x-s-jogo-microsoft-store-cover.jpg?v=1739878631','https://gaming-cdn.com/img/products/18020/pcover/1000x350/18020.jpg?v=1739878631','https://gaming-cdn.com/images/products/18020/screenshot/avowed-pc-xbox-series-x-s-jogo-microsoft-store-wallpaper-1.jpg?v=1739878631','https://gaming-cdn.com/images/products/18020/screenshot/avowed-pc-xbox-series-x-s-jogo-microsoft-store-wallpaper-2-thumbv2.jpg?v=1739878631','https://gaming-cdn.com/images/products/18020/screenshot/avowed-pc-xbox-series-x-s-jogo-microsoft-store-wallpaper-4-thumbv2.jpg?v=1739878631','https://gaming-cdn.com/images/products/18020/screenshot/avowed-pc-xbox-series-x-s-jogo-microsoft-store-wallpaper-3-thumbv2.jpg?v=1739878631','https://gaming-cdn.com/images/products/18020/screenshot/avowed-pc-xbox-series-x-s-jogo-microsoft-store-wallpaper-5-thumbv2.jpg?v=1739878631','https://gaming-cdn.com/images/products/18020/616x353/avowed-pc-xbox-series-x-s-jogo-microsoft-store-cover.jpg?v=1739878631','<iframe  width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/rPDL5zdnVw4\" title=\"Avowed Official Gameplay Trailer\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),('Xbox Series X|S','Forza Horizon 6 Deluxe','Corrida, Simulação, Esporte','L',399.63,'A Forza Horizon 6 Deluxe Edition inclui o jogo completo, o Welcome Pack e Car Pass (30 carros entregues na tua garagem, um por semana).\n\nDescobre as paisagens deslumbrantes do Japão em mais de 550 carros do mundo real e torna-te uma Lenda das corridas no Festival do Horizon. Começa a viagem como turista e explora um mundo cheio de músicas sensacionais e cultura japonesa. Constrói uma Propriedade no Vale, obtém casas impressionantes e expõe a tua estimada coleção de carros em Garagens totalmente personalizáveis. Junta-te aos teus amigos para passearem pelas estradas, participarem em Encontros de Automóveis por todo o Japão, darem asas à vossa imaginação no EventLab e construírem no CoLab do Horizon.*\n\nA tua viagem para te tornares uma Lenda do Horizon começa agora — o Japão espera por ti!\n\nVEM CONHECER TÓQUIO, A MAIOR CIDADE DO HORIZON DE SEMPRE\nDamos-te as boas-vindas ao Japão, um lugar que une contrastes impressionantes entre o rural e o urbano, à medida que desvendas os segredos escondidos no mapa mais denso de sempre do Horizon, cheio de verticalidade, biomas variados e experiências de condução espetaculares. Passeia pelos subúrbios e pelas ruas icónicas da baixa ou lança-te ao desafio nas docas e nos distritos industriais de Tóquio, a maior área urbana num jogo Forza Horizon e o lar dos entusiastas de carros.\n\nMERGULHA NA CULTURA AUTOMÓVEL JAPONESA\nConduz mais de 550 carros do mundo real, incluindo alguns muito adorados clássicos do mercado japonês, com som de motor de última geração e animações de direção atualizadas com até 540 graus de rotação do volante. À medida que exploras o Japão, coleciona carros Forza Edition especiais equipados com modificações extremas e encontra carros raros do Mercado Pós-Venda para fazeres um test drive e comprares. O caminho para ter tornares célebre vai levar-te a conhecer as Lendas do Festival do Horizon, participar em Batalhas de Touge e viver histórias autênticas enraizadas na lendária cultura automóvel japonesa.','https://gaming-cdn.com/images/products/21623/616x353/forza-horizon-6-deluxe-edition-pc-xbox-series-x-s-microsoft-store-cover.jpg?v=1772722505','https://gaming-cdn.com/img/products/19535/pcover/1000x350/19535.jpg?v=1772722466','https://gaming-cdn.com/images/products/21623/screenshot/forza-horizon-6-deluxe-edition-pc-xbox-series-x-s-microsoft-store-wallpaper-1-big.jpg?v=1